class Cuenta:
    def __init__(self, saldo):
        self.saldo = saldo

    def sumar(self, x):
        saldo = self.saldo + x

c = Cuenta(100)
c.sumar(50)
print(c.saldo)

class P:
    def __init__(self, precio, cant):
        self.precio = precio
        self.cant = cant

    @property
    def total(self):
        return self.precio * self.cant

p = P(1000, 5)
p.cant = 2
print(p.total)
